quests[55138] = { id = 55138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Hi. I'm Ambassador Blackguard.\n\nI am honored to welcome you to Orgrimmar, {race}.\n\n<He smiles unconvincingly.>\n\nAs a lifetime of adventure unfolds before you, be assured that... uh...\n\nYou know what? I've been saying this same greeting all day. Enough's enough.\n\nTalk to Chromie on top of the hourglass, then talk to your emissary. Run along.", progress = "Dis land is much less... fertile than Zandalar.", completion = "So dis is it. We begin our adventures to bring honor to the Zandalari and de Horde!\n\nLoa be with you, {name}.", objectives = "Find the Warchief's Command Board in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55142] = { id = 55142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance", description = "Thank you for meeting with me, {name}.\n\nI need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. \n\nI've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard.\n\nYou will face many challenges on the long journey ahead. Remember where you came from and make your people proud!", progress = "Welcome to Stormwind, {race}.", completion = "There you are! You must be {name}. We've been expecting you.", objectives = "Take the portal to Stormwind in the Sanctum of the Sages and meet with Ambassador Moorgard in the Stormwind Embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55146] = { id = 55146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stranger in a Strange Land", description = "Welcome to Stormwind, {race}. I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed!\n\nAh, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things!\n\nAfter that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you!\n\nHave a pleasant stay.", progress = "Enjoying your stay in Stormwind?", completion = "Wherever you venture, know that Kul Tiras is behind you.", objectives = "Find Chromie in Stormwind City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55148] = { id = 55148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclamation Rig" }
quests[55153] = { id = 55153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collaborative Construction", description = "Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects.\n\nAsk around and see what others are already working on, or just head out on your own and find a project you're interested in.\n\nConstruction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring.\n\nIf you're ever curious what construction projects are available on a given day, just ask me!", completion = "Ah, I remember my first construction project...\n\n<Waren sighs wistfully.>\n\nI wonder where I put that steam-powered pacifier?", objectives = "Find a construction project in Mechagon and help build it.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55171] = { id = 55171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spy Versus Spy", description = "Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley.\n\nSend some of our operatives to investigate what they are doing.", progress = "Hopefully we can gather information on what they're up to in Stormsong Valley.", completion = "Damn. Most of our spies haven't made their scheduled check-ins. Whatever the Horde is doing I doubt it bodes well for us.", objectives = "Complete the mission \"Spy on Warfang Hold\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55173] = { id = 55173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northbound", description = "The quilboar kidnapped the rest of the expedition and took them to the north.\n\nI heard mention of needing more sacrifices for some sort of ritual...\n\nPlease, you must rescue them!", completion = "I've got some good news and some very, very bad news.", objectives = "Scout northward and find Austin Huxworth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55174] = { id = 55174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking Meat", description = "Alaria is nearly starved to death. We need to get her something to eat!\n\nSlay some of the nearby wildlife for their meat. Bring whatever you find here to cook.\n\nIf we can help Alaria regain her strength, she might be able to tell us what happened to the others.\n\nI'll stay here and help stabilize her wounds.", progress = "Please... I need... some food...", completion = "<Alaria quickly eats the meat that you cooked.>\n\nBy the Light... I feel so much better.\n\nYou need to keep moving... quilboar have kidnapped the expedition, including Captain Garrick's son!", objectives = "Get 5 Raw Meat from wildlife around the Abandoned Camp, then cook it on the campfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55175] = { id = 55175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Road Leads", description = "My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them.\n\nFirst, we must regroup in Mezzamere. There, we at least have a foothold against the tide.", completion = "So far, these ankoan have proven themselves formidable allies.", objectives = "Travel to Mezzamere with Okani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55177] = { id = 55177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", completion = "Well, this doesn't look good...", objectives = "Speak with Delormi when you're ready to leave and investigate the disturbance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55179] = { id = 55179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retaliation Coordination", description = "Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. \n\nNow Master Shaw is the one who hasn't checked in.\n\nI need someone to go in and find our missing people and give them whatever help they clearly need.", completion = "We knew someone would come when we missed our check-in. With you as our backup the Horde isn't gonna stand a chance.\n\nShaw's further in the Valley trying to figure out what is going on in Warfang Hold. I've been trying to control the chaos here. Care to lend a hand?", objectives = "Find Kelsey Steelspark in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55182] = { id = 55182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reassembly Required", description = "Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning.\n\nI managed to salvage most of the parts for one, but I'm missing a few.\n\nFortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.", progress = "I am so excited! I love getting to work with our spy tech! Did you find what we need?", completion = "Yes! This is precisely what I needed.", objectives = "Collect Spy Salvage from Horde Forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55183] = { id = 55183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Higher Ground", description = "We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! \n\nWhile you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there.\n\nWhat? Did you think I was just sitting here polishing my knives while you were gone?\n\nWell, okay I did that too. Anyway, I'll meet you up the hill!", completion = "Once we get the listening post set up again, we won't have the range to reach Boralus, but we'll have plenty of power to get in touch with Master Shaw!", objectives = "Meet Kelsey Steelspark on the hill south of Warfang Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55184] = { id = 55184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quilboar Shadow Magic", description = "Quilboar are primitive and savage. They rarely practice any magic other than geomancy.\n\nBut these particular quilboar seem to be dabbling in shadow magic. They must be stopped.\n\nSlay the quilboar in the den. They cannot spread this magic in the island!", progress = "The quilboar are a powerful foe. Be careful.", completion = "Good work. I hope those quilboar learn that necromancy is not a path to power.", objectives = "Slay 7 Quilboar within the Quilboar Briarpatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55185] = { id = 55185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Listen Up!", description = "Okay! Once we get this up and running we should be able to send messages! In the valley at least.\n\nIt's gonna be a little bit tricky, but I've read the manual for these things cover to cover.\n\n<Kelsey slaps the top of the listening device.>\n\nI'm gonna put this thing back together. You watch out for the Horde.", progress = "Woohoo! We are up and operational!", completion = "Ha! I knew I could get this thing up and running in record time.\n\nHmm. But Master Shaw isn't responding to my signal. That's no good.", objectives = "Protect Kelsey Steelspark in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55186] = { id = 55186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down with the Quilboar", description = "From what I can gather, the quilboar are performing a shadow ritual on one of the expedition members.\n\nTheir chief is Geolord Grek'og. He is the one who seeks to drain the life from our friend.\n\nSlay Grek'og and save the captive member of the expedition. He may know where the others were taken.", completion = "Thanks for saving my life! They said this would be a run of the mill, uneventful expedition.\n\nIt definitely was NOT! And I couldn't be happier!", objectives = "Slay Geolord Grek'og.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55188] = { id = 55188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tearing at the Seams", description = "I feel odd... weak. As though something is affecting my very existence.\n\nWould you come with me, {name}? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", completion = "Well, this doesn't look good...", objectives = "Speak with Delormi when you're ready to leave and investigate the disturbance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55193] = { id = 55193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scout-o-Matic 5000", description = "You look like a {race} that needs help finding the scattered members of our alliance expedition!\n\nLuckily, you have happened to rescue the one and only Lindie Springstock, inventor extraordinaire! \n\nI've got my Scout-o-Matic 5000 all set to go. It'll fly up in the air and let you scout the entire area.\n\nI'll give you the honors. Use my Scout-o-Matic 5000 to find the rest of the expedition.", progress = "Give me a moment to re-size the Scout-o-Matic, then you can ride it!", completion = "There's no problem a little re-sizing can't fix! Let's find something to stomp those undead flat!", objectives = "Use the Scout-o-Matic 5000 to find Henry Garrick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55194] = { id = 55194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up on Supplies", description = "Quartermaster Richter was able to scavenge supplies from the wreckages on this island.\n\nWhy don't you visit her and see if she has anything that you need?\n\nYou'll want to be well equipped for whatever we encounter next.", progress = "Quartermaster Richter should have a few supplies that you could use.", completion = "All stocked up? That's great.\n\nPrivate Cole and Quartermaster Richter also found this bag in the nearby ruins. They thought you might make good use of it.", objectives = "Purchase any item from Quartermaster Richter and sell any of your items to her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55195] = { id = 55195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reverberation", description = "Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear.\n\nThe Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well.\n\nDo not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.", progress = "It warms my heart to see Hati by your side once more.", completion = "You may return here any time you wish to rekindle your bond with Hati.\n\nYou shall forever be a welcome guest in my court.", objectives = "Use the Thunderspark to summon an Essence of Hati.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55196] = { id = 55196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Harpy Problem", description = "We need to find the remaining survivors of my expedition before the ogres sacrifice them for their dark ritual!\n\nI saw one of the survivors being dragged away by some harpies. They have a roost to the north.\n\nKee-La and I will meet you up there with a scouting report.", completion = "It seems the harpies are up to no good. We'll need your help with this.", objectives = "Meet with Henry Garrick near the Harpy Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55210] = { id = 55210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Batteries Not Included", progress = "Everything old can be made new again.", completion = "These are broken, but not TOO broken... Yes, I'm sure I can get these working again.\n\nYou may keep one as your recompense.", objectives = "Collect 10 Damaged Energy Cells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55211] = { id = 55211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recharging Rustbolt", description = "Our personal generator is worthless until we recharge its empty energy cells.\n\nAs my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format.\n\nBut, once they're drained of power, most people toss the empty cells away.\n\nMost people are fools, dear test subject.\n\nWe have perfected the technology to recharge small numbers of energy cells back to full power.\n\nWill you help us test it?", progress = "We only test the best!", completion = "Wondrous work, my dear test subject!\n\nI detected unconventional electrical discharges from the NRG-100, but I see now that I was wrong to worry.\n\nIt's still in one piece. Oh, and so are you!\n\nCheer up. You've already outsurvived 5% of our test subjects!", objectives = "Use the NRG-100 to charge 6 generator energy cells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55213] = { id = 55213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energy Cells for Everyone", description = "The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today!\n\nThat charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy.\n\nAfter you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!", progress = "Empty Energy Cells can always be found on the island, but the Charging Station isn't always available.\n\nChat with that wondrous Miss Gearhart if you want to know more.", completion = "Wondrous! I hope those nasty troggs let you charge up in peace.\n\nThey simply do not comprehend technology to any degree. Frankly, I'm embarrassed for them.", objectives = "Find 5 Empty Energy Cells in Mechagon.\n\nThen, help build the Charging Station construction project and use it to charge your Empty Energy Cells.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55214] = { id = 55214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seam Stress", description = "I...I need a moment, {name}.\n\n<Delormi seems disoriented and grabs your shoulder for support. She presses her hand against her forehead and stands there for a minute. \n\nFinally shaking off whatever she was feeling, she stands up straight and faces you.>\n\nThere are gaps in my memories. Things important to me, lost now. We must stop her at all costs, {name}.", progress = "I feel so weak...", completion = "That rift, don't repair it! That's the one.", objectives = "Follow Delormi through the Time Rift.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55215] = { id = 55215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of Life" }
quests[55216] = { id = 55216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Audition", description = "Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like to provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", progress = "<Atikka breathes audibly in anticipation of your return.>\n\nHave you got the drums?", completion = "Tight stitching. Even tension. No tears or holes.\n\nYou'll do nicely.\n\n<Atikka leans in as he whispers.>\n\nMy plan is to make a set of drums from rare and powerful components. The drum's design will let you harness the raw, primal might of the slain beasts, and allow you to teach those Alliance dogs a lesson they won't soon forget. \n\nUsing the drums will require a special mallet, but fear not. Once our work is done, I will teach you how to craft a mallet for yourself.", objectives = "Craft 3 Drums of the Maelstrom and bring them to Atikka Moonchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55217] = { id = 55217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repaying the Life Debt", description = "When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us!\n\nI need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection.\n\nI won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us.\n\nFind her, tell her I sent you, and that this absolves her debt.", completion = "<You explain your mission and relation to Atikka.>\n\nI see. Of course I'm more than willing to help, especially since it's Atikka.\n\nHowever, doing so is going to take a bit more work on your end, if you don't mind.", objectives = "Speak with Sheza Wildmane in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55218] = { id = 55218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sheza's Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nI don't know how, but the Venture Company must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be in the bluffs to the East until someone buys them.\n\nHowever you get the skins, consider them yours.", progress = "How was she?", completion = "<You explain what happened in Mulgore.>\n\nBah! Wretched goblins and their lust of coin!\n\n<Attika takes a deep breath to steady himself.>\n\nI... Am sorry you had to see that. I just find it so infuriating when our fight is made harder so one of those green-skinned runts can steal your last copper.", objectives = "Retrieve the Rare Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55219] = { id = 55219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping by the Base", description = "When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums.\n\nTorv usually keeps to himself, but he is as brilliant as he is insane.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.", completion = "Atikka sent you? Ha! How is the old steer?!\n\nHmmm... scales you say.\n\n<His eyes flick back and forth as he looks off into the distance. His expression quickly shifts from a grimace to one of delight.>\n\nI got it!", objectives = "Speak with Torv Dubstomp in Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55220] = { id = 55220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bass Fishing", description = "Have you heard of people taking small golden carp as pets?\n\nWell, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present.\n\nCenturies ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free.\n\nNow, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf.\n\nKill it. Take his scales back to Atikka.", progress = "Did you meet with Torv yet?", completion = "<After hearing your retelling of Torv's plan, Atikka bursts into laughter.>\n\nA centuries old goldfish?!\n\nI told you he was insane!\n\nAhhh, good work. Glad to see you weren't eaten by a guppy.", objectives = "Collect Brilliant Golden Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55221] = { id = 55221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Bones", description = "When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula.\n\nWhatever it was, it must have been strong, making it the perfect source for the bone elements of the drums.\n\nGo to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find.\n\nIf you come across any of those damned Alliance, show them no mercy. They did this to themselves.", progress = "Did you get the bones?\n\nDid the Alliance give you any trouble?", completion = "These look good.\n\nIt makes me even happier knowing this was something the Alliance was after, and that you mucked that up for them! Heh!", objectives = "Collect 18 Unwaning Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55222] = { id = 55222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Some Noise", description = "We have everything we need to craft the drum, except the Earth Mother's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nIt will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children.\n\nWhile I'm doing that, you will need to craft the drum itself.\n\nNot too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.", progress = "<Clearly exhausted, Atikka is trying to remain composed.>", completion = "<Atikka lets out a beleaguered breath, before turning his head to face yours, smiling weakly.>\n\nWe've done it, {name}.", objectives = "Craft 6 Drums of Primal Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55223] = { id = 55223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instruments of Destruction", description = "Our work is almost finished.\n\nThese drums, while powerful, are practically useless here in port.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", completion = "I'm glad to see you back in one piece.\n\nIn hindsight, I suppose I could have shown you how to make the mallet before you left, but everything seems to have worked out well.\n\nNow then, let me show you how to make the Mallet of Thunderous Skins...", objectives = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55224] = { id = 55224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rank 2 - Poen test", description = "Gather corrupted ink sacs from the Nazothian Brain squids. \n\nThe naga use them to control us, let's see if it works the other way.You will learn:" }
quests[55225] = { id = 55225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Juices" }
quests[55226] = { id = 55226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive the Enemy" }
quests[55227] = { id = 55227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Aeonian Artisan", description = "Good day, friend!\n\nA Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty.\n\nI gave her your name, and she asked me to ask you to find her in Boralus Harbor.\n\nShe didn't say what she needed my best student for, but the way she acted makes me think that it is for something big.\n\nHead on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!", completion = "Goddess be praised!\n\nWe have much to discuss.", objectives = "Meet the Night Elf Leatherworker in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55228] = { id = 55228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Audition", description = "Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you.\n\nIf you are willing, I would like provide you with a test to see how well you can work leather.\n\nBring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency.\n\nIf your work is up to par, I will inform you of my plan.", progress = "Do you have the drums?", completion = "Clean lines. Even tension. No tears or holes.\n\nVery well.\n\nMy plan is to make a set of drums from rare and powerful components that will let you harness the raw, primal might of the slain beasts.\n\nWith this power, you will teach the Horde that home is not a place that can be burned, hope is not something that can be slain, and that we are stronger than flame. \n\nThe drums will require a special mallet to use, but once our work is done, I will teach you how to craft this mallet for yourself.", objectives = "Craft 3 Drums of the Maelstrom and bring them to Daniss Ghostdancer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55229] = { id = 55229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repaying the Debt", description = "I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished.\n\nI need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection.\n\nI managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal.\n\nFind him, tell him I sent you, and that this will absolve his debt to me.", completion = "<You explain your mission and relation to Daniss.>\n\nI see. Of course I'm more than willing to help. She may be a T'lara, but I do owe her my life.\n\nHowever, there is a slight issue that will need to be dealt with.", objectives = "Speak with Telonis in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55230] = { id = 55230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telonis' Prized Leather", description = "I have a stash of extremely rare leathers, or... rather, I did.\n\nA group of thieves must have heard how valuable my collection was because they stole it!\n\nAnd THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\"\n\nThe note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer.\n\nHowever you get the skins, consider them yours.", progress = "How is he holding up?", completion = "<You explain what happened in Stormwind.>\n\nTypical humans. Extorting allies because only their suffering matters.\n\n<Daniss takes a deep breath to steady herself.>\n\nI am sorry, {name}. I spoke out of frustration.\n\nI'm no stranger to war, but Sylvanas' tactics have made this one exceptionally taxing. I didn't mean to discourage their... resourcefulness. I simply wish it hadn't come to it.\n\nAt this time, we must keep our faith in the Alliance.", objectives = "Retrieve the Rare Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55231] = { id = 55231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other Ghostdancer", description = "When the Legion was attacking, my partner went to Val'sharah to fight the demons.\n\nMevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him.\n\nIf there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him.\n\nHead to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.", completion = "Daniss sent you? Is everything alright?\n\n<You explain the plan and need for scales.>\n\nHmmm... scales you say.", objectives = "Speak with Mevris Ghostdancer in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55232] = { id = 55232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mevris' Menace", description = "There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here.\n\nIt's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook.\n\nI sent a team to handle it, but they haven't returned.\n\nGo out there, kill it, and take its scales to Daniss.\n\nAnd when you see her, tell her that I said...\n\n<Mevris pauses as he thinks of his words, and the meaning they carry.>\n\nNothing.", progress = "Have you met with Mevris?", completion = "<After hearing your retelling of Mevris' plan, Daniss nods thoughtfully.>\n\nI'm glad you were able to assist him. He has been gone for some time now. Hopefully with this creature now deceased, there is one less obstacle before he can come home.\n\nAnd good work with the scales. These appear to be perfect for the task.", objectives = "Collect Brilliant Azure Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55233] = { id = 55233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Picking Bones", description = "When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound.\n\nApparently they're scrounging around the remains of a massive creature that has washed ashore.\n\nWhatever it was, if the Horde wants it, we need to make sure they don't get it.\n\nFind the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums.\n\nShow them no mercy, {name}.", progress = "Have you dealt with our mutual problem?", completion = "These bones look good.\n\nI'm thrilled to hear that the Horde bought nothing with their lives.", objectives = "Collect 18 Unwaning Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55234] = { id = 55234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Some Noise", description = "We have everything we need to craft the drum, except Elune's blessing. \n\nThe drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink.\n\nWith Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try.\n\nWhile I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.", progress = "<Clearly exhausted, Daniss is trying to remain composed.>", completion = "<Daniss lets out a beleaguered breath, before turning to face you, smiling weakly.>\n\nWe did it, {name}.\n\nThey may have called me \"T'lara\", a warrior armed only with words, but those words have given us the strength of a goddess.\n\nWith these drums, we can break the Horde.", objectives = "Craft 6 Drums of Primal Might.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55235] = { id = 55235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instruments of Destruction", description = "There is one last thing we need to do.\n\nThese drums, while powerful, are practically useless here in town.\n\nIf you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines.\n\nLook for someplace centralized in each territory to place drums.\n\nOnce you return, I'll show you how to make the mallet needed to utilize the drums.", completion = "You've returned! I take it all went well?\n\nIn retrospect, I could have shown you how to make the mallet before you left, but everything seems to have worked out well.\n\nNow then, let me show you how to make the Mallet of Thunderous Skins...", objectives = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55242] = { id = 55242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Goblin in Need" }
quests[55243] = { id = 55243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", completion = "<The Child of Torcali holds her head high.>", objectives = "Find the Child of Torcali in the Savagelands and rescue her from danger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55244] = { id = 55244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", completion = "<The Child of Torcali lovingly headbutts your leg.>", objectives = "Play with your direhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55245] = { id = 55245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eat Like a Direhorn", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", progress = "<The Child of Torcali wiggles impatiently.>", completion = "<The Child of Torcali blinks trustingly up at you and makes a warm rumbling sound.>", objectives = "Feed the Child of Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55246] = { id = 55246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Even Greener Pastures", description = "Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry.\n\nShe got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe.\n\nShe is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.", completion = "<The Child of Torcali seems very pleased with herself.>", objectives = "Find the Child of Torcali and lead her back to her pen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55247] = { id = 55247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trust You've Earned", description = "I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship.\n\nShe is large enough now that she can bear you wherever it is that you wish to go.\n\nI had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back.\n\nCongratulations, {name}.", progress = "<Li'zal rubs her head and groans.>", completion = "I could not stop her. She rammed de gate...\n\nLike a thing possessed...", objectives = "Retrieve the Direhorn Saddle in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55248] = { id = 55248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greener Pastures", description = "You have done an adequate job keeping de little one fed, but sometimes they just want something else.\n\nI did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it.\n\nIf you have trouble bringing her home, you might try a bribe.", completion = "<The Child of Torcali seems very pleased with herself.>", objectives = "Find the Child of Torcali and lead her back to her pen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55249] = { id = 55249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Away From the Herd", description = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns.\n\nPerhaps she could use a distraction.>", completion = "<The Child of Torcali lovingly headbutts your leg.>", objectives = "Help your direhorn cheer up.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55250] = { id = 55250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Growing Appetite", description = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", progress = "<The Child of Torcali wiggles impatiently.>", completion = "<The Child of Torcali blinks trustingly up at you and makes a warm rumbling sound.>", objectives = "Feed the Child of Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55251] = { id = 55251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Daughter of Torcali", description = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors.\n\nIn this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time.\n\nBest find her before she gets hurt.", completion = "<The Child of Torcali holds her head high.>", objectives = "Find the Child of Torcali in the Slough and rescue her from danger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55252] = { id = 55252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Loa Without a Temple", description = "I have given some thought about your situation, {name}.\n\nIt is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. \n\nBut dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child.\n\nTake dis offering to her shrine and ask for her boon... and her forgiveness.", progress = "<The great direhorn looks down upon you.>", completion = "<A warm but thunderous voice enters your mind.>\n\nYou have come to redeem yourself. Good. Let us begin.", objectives = "Deliver L'kala's offering to Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55253] = { id = 55253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Faith", description = "<Torcali's voice enters your mind.>\n\nI have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it.\n\nI do not forget, but I can forgive.\n\n<The enormous direhorn touches the offering bundle with her nose.>\n\nAs my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.", completion = "<The Child of Torcali peers sleepily up at you and rumbles contentedly.>", objectives = "Deliver the Blessed Offering to your direhorn hatchling in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55254] = { id = 55254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unending Sleep", description = "<The direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it.\n\nIt's probably been too long. You should speak to Beastlord L'kala.>", completion = "I see you have noticed de state of your hatchling.\n\nGiven it is your responsibility, I will accept dat you did not know what you were doing when we started dis whole affair.\n\nI hope you are ready to change dat.", objectives = "Speak to Beastlord L'kala in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55258] = { id = 55258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleep, Eat, Repeat", description = "<The Child of Torcali pushes the sack of herbs around with her snout.\n\nShe then looks to you and stomps eagerly in place.>", progress = "<The Child of Torcali pushes her snout into your hand in search of food.>", completion = "<The Child of Torcali trumpets in satisfaction.>", objectives = "Feed the Child of Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55264] = { id = 55264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55298] = { id = 55298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing For Something Bigger", description = "There's a huge fish lurking these waters, and it's been causing lots of problems! \n\nIt eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day!\n\nI've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?", progress = "Did you get me the items?", completion = "Great work, {name}.  Now I can build the Minnow Vac!", objectives = "Find the Anodized Sentry Fish, Jarmouthed Goby and the Suction Tube.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55299] = { id = 55299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bottom Feeding Stinkfish", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish looks to have adapted to survive in the shallow water pools around the trash heaps. It smells awful, the smell probably protects it from any predators. I want to catalogue this and release it before this smell sticks to me!", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55300] = { id = 55300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cycle of Life" }
