quests[55305] = { id = 55305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bolted Steelhead", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish appears to have been manufactured! The workmanship is quite sophisticated. I want to catalogue this and release it for further observation.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55306] = { id = 55306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pond Hopping Springfish", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish has adapted itself to allow it to hop between shallow pools of water. I will catalogue it and release it back into a nearby pool.  We'll then see where it hops too!", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55307] = { id = 55307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowy Cave Eel", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish looks to have adapted to survive in dark caves of Mechagon. I will catalogue it and return it to a nearby cave.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55308] = { id = 55308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mechanical Blowfish", description = "<Danielle Anglers may be interested in this fish.>", completion = "A strange mechanical fish that appears to be modifying itself for survival in these waters. An amazing discovery!", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55309] = { id = 55309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spitting Clownfish", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish has developed an unusual behavior. It most likely is imitating the actions of surrounding creatures. I will catalogue it and then release it immediately.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55310] = { id = 55310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sludge-fouled Carp", description = "<Danielle Anglers may be interested in this fish.>", completion = "Something horrible has happened to this fish. It maybe worth further investigation of the waters where you found it.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55311] = { id = 55311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energized Lightning Cod", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish radiates electricity. I suspect it has been feeding on underwater power cables. A most interesting find, which I will catalogue immediately!", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55312] = { id = 55312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solarsprocket Barbel", description = "<Danielle Anglers may be interested in this fish.>", completion = "This mechanical fish appears to be powered by sunlight. I will catalogue this find and return it to its pond.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55313] = { id = 55313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tasty Steelfin", description = "<Danielle Anglers may be interested in this fish.>", completion = "This fish appears quite healthy and probably tastes quite delicious. I will catalogue this and then probably cook it for dinner.", objectives = "Take the fish to Danielle Anglers.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55319] = { id = 55319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tonk the Terrible", description = "<This TK looks like it could be a good racer in the Roadrash Race.\n\nCrash Wheeler at the Roadrash Racetrack has the final say on what's allowed, though.>" }
quests[55339] = { id = 55339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidying Up", description = "Ionized Minnows are a scourge of these waters. They strip the ocean floors of any food, making it difficult for other species to survive.\n\nThese fish have little to offer other than being a food source for larger fish. I want to see these larger fish, so I have a plan to clear the waters of these minnows and lure the bigger fish out from its hiding place.\n\nLet's start by using my Minnow Vac to catch Ionized Minnows for me.", progress = "Did you catch any fish?", completion = "With these minnows, we can build the trap.", objectives = "Catch 200 Ionized Minnows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55340] = { id = 55340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55341] = { id = 55341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55342] = { id = 55342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55343] = { id = 55343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55344] = { id = 55344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calligraphy" }
quests[55345] = { id = 55345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ranger's Pupil", description = "Thank the abyss you're here, champion!\n\nI am Moorgoth, tracker of fearsome foes in dark places. Anyone in the Trueshot Lodge will vouch for my credentials.\n\nDark Ranger Velonara and I are good friends, and I fear she is in peril.\n\nShe's been training an apprentice dark ranger. Newly raised, she said. At any rate, her pupil ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about all this. Could you check on her safety?", sourceObjective = "Find Dark Ranger Velonara in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[55346] = { id = 55346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Ranger's Pupil", description = "I am Moorgoth, hunter of fearsome foes and hero of the Trueshot Lodge.\n\nYou are a renowned champion of the Alliance, but I've been told you save those in peril. Please hear me out.\n\nI am friends with a ranger named Velonara. She serves the Horde, but I assure you she is a noble soul.\n\nShe's been training an apprentice ranger who disappeared after receiving a letter from his brother. Velonara has gone to Tirisfal Glades to find him.\n\nI have a bad feeling about this. Would you check on her safety?", sourceObjective = "Find Dark Ranger Velonara in Tirisfal Glades.", sourceObjectiveStatus = "unverified-source-field" }
quests[55348] = { id = 55348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies from the Rustbolt Resistance", description = "The Resistance appreciates all the help you've given us.\n\nPlease take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", completion = "The Resistance stands strong, thanks in part to your prevailing efforts.\n\nYour efficiency has earned you additional resources.\n\nPlease expend them in endeavors optimized to ensure the continued success of the resistance.", objectives = "Speak with Prince Erazim in Rustbolt for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55350] = { id = 55350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault: Amathet Advance", description = "The Amathet seek to claim the Forge of Origination for their own. We must not allow it to fall into their hands again!\n\nOur men are defending the entrance, but they will be overwhelmed if the entire might of the Amathet advances upon them. \n\nDo what you can to route their forces before its too late.", progress = "The Amathet must be stopped!", completion = "Hah! You showed those dusty zealots what a true warrior looks like.\n\nWell done.", objectives = "Drive back the Amathet Assault in Uldum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55354] = { id = 55354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vir'nall Front" }
