quests[55359] = { id = 55359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Ascendancy" }
quests[55360] = { id = 55360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unsealed Tomb" }
quests[55361] = { id = 55361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Shaman", description = "Pardon me, {class}. I am in need of your assistance.\n\nOur shaman, Farseer Ori, left the camp some days ago to investigate a nearby disturbance in the elements. He took his apprentice with him, a young initiate named Odari. Neither have returned.\n\nI am leading an expedition to find them and return them here safely. Nazjatar is full of dangers. The skills of an accomplished {class} like yourself could prove most useful.\n\nWill you help me return the lost shaman to safety?", completion = "It is good you are here. We must speak quickly. I fear for the safety of my master...", objectives = "Locate Apprentice Odari at Dragon's Teeth Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55362] = { id = 55362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Fury", description = "The naga have angered the elements and disrupted the natural order. We must restore the balance before it is too late.\n\nA Farseer maintains a deep connection with the elements. When the naga forces imprisoned my master, the natural balance was disturbed.\n\nTake the Stone of Elements and use it to pacify the enraged water elementals throughout Dragon's Teeth Basin.\n\nUltimately, our only solution is to rescue Farseer Ori and bring him back alive, but the Tidestone could buy us precious time...", progress = "We must restore the balance before it is too late!", completion = "You have done well. I can sense that the elemental balance is close to being restored to its natural state.", objectives = "Pacify 8 Tide Surgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55363] = { id = 55363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue The Farseer", description = "My master, Farseer Ori, has been imprisoned by the forces of Queen Azshara.\n\nFarseer Ori was captured while performing a sacred ritual to call upon the elements for guidance. I managed to escape, but the ritual has been left unfinished.\n\nIf we do not rescue my master soon, the elements will grow even more restless.\n\nThe elemental balance must be maintained. I fear what may become of my clan and our bond with the elements if Farseer Ori is not returned to us.", completion = "I fear whatever fate may have awaited me had you not rescued me when you did.", objectives = "Rescue Farseer Ori.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55373] = { id = 55373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knock 'Em Out The Box", description = "Steelarm Pillagers have been taking all our parts and selling them to Bondo's gang.\n\nLast night they stole all our Spiderspring Gears. The parts are in a bunch of crates they're guarding.\n\nWe need you to get our gears back, and show those Steelarm Pillagers they should pick on someone else.", progress = "Get our gears back.", completion = "Now we can assemble the mount's main spring drive!", objectives = "Take out those Steelarm Pillagers and get 10 Spiderspring Gears back.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55374] = { id = 55374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbance Beneath the Earth", description = "Manifestation of dragon essence detected. Location: Highmountain. \n\nAssuming successful retrieval, calculations indicate 92.7 percent probability of empowering Heart of Azeroth.\n\nTheory: By combining dragon essence with sufficient quantities of Azerite within Heart Forge, previously undiscovered abilities may manifest within Heart.\n\nAs Speaker Magni would say: \"Get to work, champion.\"", progress = "What brings you here, {name}?", completion = "We must make haste. I feel the essence of my kin calling to me.", objectives = "Travel to Highmountain and investigate the essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55375] = { id = 55375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55378] = { id = 55378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Shimmerscale", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 20 Shimmerscales to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55379] = { id = 55379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Star Moss", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 20 Star Moss to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55380] = { id = 55380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Storm Silver Ore", progress = "I've received an urgent request from Tinkmaster Overspark.\n\nThese supplies are needed!", completion = "Thank you, {name}. Your contribution has been logged in our records for posterity to appreciate!", objectives = "Bring 10 Storm Silver Ore to Gila Crosswire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55381] = { id = 55381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Storm Silver Ore", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 10 Storm Silver Ore to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55382] = { id = 55382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Shimmerscale", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Shimmerscales to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55383] = { id = 55383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Requisitions: Star Moss", progress = "Gazlowe's orders are in: He wants these supplies ASAP.\n\nYa got the goods?", completion = "Thanks for pitchin' in.\n\nI'll make sure Gazlowe and Prince Erazmin know these came from you.", objectives = "Bring 20 Star Moss to Skaggit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55384] = { id = 55384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settling In", description = "Whatever Azshara is up to, this *ahem* great new landscape we have found ourself in is terribly inconvenient. \n\nToo many getting too close to our home. We have moved most of the refugees deeper into the cave.\n\nCould you ask Telur to move our calling conch inside? \n\nGrab some of Slen's Elixir and check in with Vim.\n\nOnce it is set up, test it out! \n\nI'm off to do a progress check!", completion = "We won't be missing that sound, land friend!", objectives = "Set up the calling conch and make the rounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55385] = { id = 55385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Pens", description = "Some of our scouts have not returned.\n\nThey have been keeping an eye on the Zanj'ir Slave Pens. \n\nThe naga there take our people. They break their minds. Our scouts watch them, and when there is a window, they rescue them.\n\nSomething is going on. We need to get them home!", progress = "Did we find everyone?", completion = "Thank you, {name}, for helping us.\n\nWe have lost too many, we can't stop here!", objectives = "Find the scouts.\n\nIf you lose Neri, return to the conch to call her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55389] = { id = 55389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55390] = { id = 55390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Darkness, I Dream", description = "The green dragonflight calls for aid. The Emerald Dream, which they have watched over for eons, has been invaded by terrible creatures of the Void.\n\nMerithra of the Dream is attempting to combat the threat, but she cannot do so alone. If you seek to empower the Heart of Azeroth with the strength of the green dragonflight, you must first help Merithra save it.\n\nMeet her at the Temple of Elune in Val'sharah, and assist her however you can.", completion = "Thank you for coming, champion. My mother once placed her trust in mortals, and I find that I must call upon them once again. \n\nI simply do not know how to fight this battle on my own.", objectives = "Meet Merithra at the Temple of Elune in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55392] = { id = 55392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Dreamway", description = "We have little time, so I will be brief.\n\nThe Emerald Dream is under attack. The shadows of the Void are on the rise, and not even the Dream is beyond their reach. Many of my kin have already been slain, and still more are at risk.\n\nWe must enter the Dreamway and save what remains of my dragonflight before it is too late.", completion = "Now you see how dire our situation is. The Void is consuming us!", objectives = "Speak with Merithra to enter the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55393] = { id = 55393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null the Void", description = "The green dragonflight cannot stop this tide of Void creatures on our own. Not with our reduced strength.\n\nPlease, lend us your might and drive them from the Dreamway before they can enter the waking realm.", completion = "Thank you. With fewer of those Void creatures about, we can attempt to secure the Dreamway.", objectives = "Slay Void invaders in the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55394] = { id = 55394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Emerald", description = "Kalecgos tells me that you seek the power of the dragonflights in its most essential form. There may be something here that can help you.\n\nFragments of our latent power have coalesced here in the Dream.\n\nThey are scattered about the Dreamway, where my kin have fallen. Within the Dream, you should be able to wield those fragments in their raw state.", progress = "Have you collected the shards?", completion = "This power once belonged to my flight, passed down through my mother when she was empowered by the Titan, Eonar.\n\n<Merithra lowers her head for a moment.>\n\nIf you are to use it to help save our world, then we must first bind these fragments together.", objectives = "Collect Emerald Shards in the Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55395] = { id = 55395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Close Your Eyes", description = "The Void assaults us as we sleep! Those who it ensnares may never wake again.\n\nThey can only be roused by powerful magic native to our dragonflight. The shards that have formed near our fallen kin may be exactly what is needed.\n\nIf we succumb to slumber in the Void, we will be lost forever. Please, aid us!", completion = "Karkarius... and Thessera, too? I never thought...\n\nIt saddens me terribly that some would choose to die instead of fight. This life may be fraught with hardship, but it is the only one we have.\n\nI am grateful that you tried to save them, even if they were not willing to be saved.", objectives = "Wake Thessera, Verdisa and Karkarius from Void dreams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55396] = { id = 55396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Stuff Dreams Are Made Of", description = "All that remains is to throw the emerald fragments you collected into the lake. I will use my power to bind them together.\n\nIf this works, they will be reforged into a powerful dragonscale that you can use to empower the Heart of Azeroth.\n\nI believe that my mother would be pleased that some of our power will go toward saving the world. I hope she would be proud of us.", progress = "These waters may no longer be tainted by the Void, but the green dragonflight must remain vigilant lest it ever return.", completion = "You hold the coalesced power of the green dragonflight in your hands, {name}. I trust you will use it well.", objectives = "Toss the Emerald Shards into the lake and collect the Dreamglow Dragonscale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55397] = { id = 55397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before I Wake", description = "It is as I feared. We cannot fuse the shards together until the Void has been driven from this place.\n\nQuickly, strike down these aberrations. I suspect the source of the corruption will not sit idle in response.", progress = "The Void is at its strongest here. I feel at fault for allowing it to spread unhindered.", completion = "To think something so dark, so terrible, festered here for this long. We are truly lost.", objectives = "Destroy all Grips of Horror and the Void Horror.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55398] = { id = 55398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Long Awake", description = "There is nothing more you can do for us here, champion. You have the power you sought, and the Emerald Dream is fighting back against the Void.\n\nBring this dragonscale back to Magni and the others. I will meet you in the Chamber of Heart to help infuse it into the Heart of Azeroth.\n\nAs for my flight, our long vigil must continue... or we will be lost to the Void.", completion = "This place is incredible, and I am proud to stand with the other dragonflights in defense of Azeroth. Let us hope that this essence will turn the tide in our favor.", objectives = "Return to Merithra in the Chamber of Heart with the Dreamglow Dragonscale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55400] = { id = 55400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take My Hand", description = "Beneath us lies the former home of the dragon Neltharion. You may know him as Deathwing. \n\nIf your titan watcher friend detected an essence of dragon magic coalescing nearby, it may be an echo of the power of the dragonflights. Such power will be coveted by others as well.\n\nThis force is likely originating from the most potent area within the lair--the decaying bones of my kin slain in the throes of Deathwing's fury.\n\nWe must go before the essence falls into the wrong hands.", completion = "I hope the trip down was not as...rocky for you as it was for me.", objectives = "Speak to Navarrogg to travel to the Dragon's Spine in Neltharion's Lair.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55407] = { id = 55407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Spine", description = "It is plain that the situation here is dire.\n\nThe power of the black dragonflight echoes around us, and the earth is reeling in response. \n\nI have heard tales of ruptures like these on Kul Tiras and Zandalar. The elementals have been driven into a frenzy, and they bar our way from seeking the essence.\n\nIf we are to preserve the tenuous balance of the elements here, the wounds must be mended, {name}.", progress = "Are the wounds healed, {name}?", completion = "The fissures are healed? Good. We can proceed.", objectives = "Seal the Azerite Fissures in The Dragon's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55412] = { id = 55412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55424] = { id = 55424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspirant Elynna", description = "{name}! You've returned to the Maw! Glory be with you!\n\nI have news. It seems that one of the aspirants lost in the attack on Honorveil is being held here, in the Jailor's Armory. Her name is Elynna, and she's on the tenth floor.\n\nThat's all I know for now. We shall speak again when I know more.", objectives = "Find Aspirant Elynna on the tenth floor of the Jailer's Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55425] = { id = 55425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dominating the Indomitable", description = "With the wounds healed, I can clearly sense the dragon essence. Unfortunately, it seems to emanate from the earthen giant before us.\n\nI will address the creature. Let us hope it listens to reason... but be prepared for anything.\n\nWhen Deathwing shattered the World Pillar in Deepholm, he earned the ire of the Stonemother and her forces. I fear this being may blame me for my father's crimes.", progress = "The essence of my flight is powerful indeed.", completion = "Now that we have the essence, I pray the earth finds peace once again.", objectives = "Confront Ma'haat the Indomitable in the Dragon's Spine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55426] = { id = 55426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Will It Grow?", description = "<The small seed is starting to sprout. Perhaps there's a place nearby that it could be planted.>", progress = "What have you brought me?", completion = "Ah, what do we have here? A rare plant, indeed! \n\nCoral Lashers are remarkable specimens. They grow rapidly after every meal, gaining both size and strength. \n\nThe largest ones are exceptional, but also quite dangerous, so feed with caution.", objectives = "Plant the Germinating Seed within Fertile Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55431] = { id = 55431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquest's Reward", objectives = "Your prowess on the field of battle is without peer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
