quests[55451] = { id = 55451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Fireball Red", description = "<Marvelous Martini could make use of this item.>", completion = "What a bold color for a mechanocat. I could see you riding this!", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55452] = { id = 55452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Fel Mint Green", description = "<Marvelous Martini could make use of this item.>", completion = "A delicious color choice. I can almost taste the fel.", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55454] = { id = 55454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Lemonade Steel", description = "<Marvelous Martini could make use of this item.>", completion = "What a tasty color for a mechanocat!", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55455] = { id = 55455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Mechagon Gold", description = "<Marvelous Martini could make use of this item.>", completion = "Good or bad, it makes a statement!", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55456] = { id = 55456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Copper Trim", description = "<Marvelous Martini could make use of this item.>", completion = "A unique choice, for those that want to be different.", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55457] = { id = 55457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Overload Orange", description = "<Marvelous Martini could make use of this item.>", completion = "One of my favorites!", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55462] = { id = 55462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wanderer's Call", description = "Greetings, small thing.\n\nDe Great Wanderer asked this one to collect you. She has a task for you and de little beast to complete.\n\nJo'nok's loa is patient, but he would not keep her waiting.", completion = "<The great direhorn regards you with one enormous eye. A voice enters your mind.>\n\nI am pleased by what I see. I would ask more of you, now.", objectives = "Speak to Torcali in the Savagelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55463] = { id = 55463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid From Nordrassil", description = "Look at what they've done to this island, {name}.\n\nNature is nearly extinguished, its death cry falling on the deaf ears of mechagnomes.\n\nBut I have heard the teeny tiny animals of Mechagon, and bring aid from afar!\n\nIt won't be easy to restore balance to a land so severely wounded. Nature's scars run deep here.\n\nThankfully, we are not alone. I've brought living sap from Nordrassil, the World Tree of Mount Hyjal. Use it to regrow the forests and speed nature's recovery in this land.", completion = "A small steps towards bringing balance to Mechagon.\n\nI thank you, {name}. And so do the adorable lil' animals who will find home in those trees you grew. I will report our progress back to the druids of Nordrassil.", objectives = "Kill 8 Sawblade Clearcutters and use the Living Sap of Nordrassil to regrow 8 stumps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55465] = { id = 55465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Must Go Deeper", description = "These shards can only do so much in their current state. They are broken and scattered... not unlike my kin.\n\nWe must bring them together.\n\nLet us go deeper into the Emerald Dream. I know of a place where we can reforge the shards into a dragonscale. With it, you can empower the Heart of Azeroth with the essence of my dragonflight. We must go to the ancient heart of the Dream, where my mother once rested.\n\nSpeak with me when you are ready to delve deeper.", completion = "The extent of the corruption is more dire than I thought. My mother used to love this place... and now it withers within the Void's grasp.", objectives = "Speak to Merithra to travel deeper into the Emerald Dream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55466] = { id = 55466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vuk'laz the Earthbreaker" }
quests[55469] = { id = 55469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Zin-Azshari", description = "We need something to deal with the guardian of the Tidestone, {name}.\n\nOur new allies here say that there is a naga enclave located in the ruins of Zin-Azshari. If there is anything potent enough to counter Azshara's sorcery, it will be in the ruins of her capital city.\n\nThe First Arcanist will accompany you, champion. She will be best equipped to assist you in matters both historical and magical while you search.\n\nGood luck.", completion = "Is that what I think it is?", objectives = "Meet First Arcanist Thalyssra in the ruins of Zin-Azshari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55481] = { id = 55481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Palace", description = "We cannot hide here forever, {name}. We have to deal with Azshara.\n\nWe will need to assault her palace but we do not know what defenses she has in place. I dispatched a scouting team while you were gone and they have not reported back.\n\nI cannot afford to lose any more people. Speak with Spiritwalker Ussoh. His abilities will let us see where the scouts are.", progress = "Have you spoken with Ussoh yet?", completion = "The Tidestone! Of course....", objectives = "Speak with Spiritwalker Ussoh to observe the scouting party.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55482] = { id = 55482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Connection", description = "A communication crystal! Have they survived this long?\n\nWe used to use these to communicate. They allowed us to project images of ourselves to other nearby crystals to see and speak with those on the other end.\n\n<Thalyssra examines the crystal for a few moments.>\n\nThe magic has long since depleted from the crystal. We will need a power source, preferably something just as old as this.\n\nCheck our surroundings, but be careful. It is too quiet out here....", progress = "Have you found anything to power the crystal?", completion = "This should work if they have sufficient power....", objectives = "Search the ruins of Kal'methir for magical relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55485] = { id = 55485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrors in the Deep", description = "Azshara knows we are here. Still, we must press on.\n\nBe careful, though. There is a... wrongness coming from the water. It is unlike the magic of old, but more ancient and terrible.\n\nTraverse the canals and find the source of corruption. If we are to search Zin-Azshari, we cannot let any relics fall into the hands of even darker powers.", completion = "His influence is spreading...", objectives = "Defeat 10 corrupted creatures and the source of the corruption.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55486] = { id = 55486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Telemancy", description = "The nightborne are no strangers to this place. It was once our capital too, long ago.\n\nBefore the Sundering and erecting the shield over Suramar we used to travel freely to Zin-Azshari. Oculeth had a workshop in these estates. \n\nPerhaps it might contain some secrets or magic that went undisturbed by the survivors.", progress = "Have you found the workshop yet?", completion = "Why am I not surprised. Still, these notes may prove useful.", objectives = "Investigate Oculeth's old workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55488] = { id = 55488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak with the Dead", description = "So many souls perished beneath the waves. Too many sacrificed for her ambition.\n\nIt is strange that the spirits here have not departed. I wonder if they even know they are dead?\n\nStill, their knowledge might be useful to us. If you could question the spirits, they might be able to point us in the right direction.", completion = "The Javelins? I thought them lost!", objectives = "Question the spirits in the Highborne Estates to discover something useful.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55489] = { id = 55489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Handmaiden's Tale", description = "The Javelins of Suramar!\n\nWielded by Azshara herself, they contain immense magical power. She has always had a fondness for bestowing favors on her favorites, but I never suspected she would give one something so valuable as one of her Javelins. This foe must be formidable indeed.\n\nNevertheless, {name}, we cannot let this opportunity pass us. Defeat the handmaiden and retrieve the relic!", progress = "We cannot let her get away.", completion = "This just might work.", objectives = "Retrieve the Javelin of Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55490] = { id = 55490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We'll Poke Their Eye Out", description = "The Javelins were some of Suramar's finest creations before the Sundering. Their magic is ancient and potent. Perhaps strong enough to defeat Azshara's wards.\n\nHurry back to Newhome. We must tell the others of our success here. You have done well.", completion = "With this, we can secure the Tidestone.", objectives = "Return to Lor'themar Theron in Newhome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55497] = { id = 55497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Friendly Face", description = "An essence of black dragonflight magic is not to be trifled with, {name}.\n\nMy flight has been the pawn of dark forces in the past. I owe it to my fallen kin to see that our power is never used for evil again.\n\nI would like to journey with you and meet your allies. Perhaps my knowledge can help you use this essence to defend our world.", progress = "Was MOTHER's analysis correct?", completion = "I like this tauren friend o' yers. Here's hopin' he stays free o' corruption!\n\nOkay, time tae see what MOTHER can do with that essence!", objectives = "Meet with Spiritwalker Ebonhorn and Magni Bronzebeard in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55498] = { id = 55498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", completion = "I've always been fascinated with The Age of Order, but never have I found such an interesting crystal. \n\nI will study this artifact. Perhaps I chose the right time to conduct my research.", objectives = "Bring the Shimmering Timewarped Crystal to Tempra in Stormshield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55499] = { id = 55499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shimmering Crystal", description = "Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white.\n\nWhen your vision returns, you feel something within you pulling you toward Ashran.", completion = "The Age of Order shaped much of Draenor's future in many timelines. With each new artifact we find, we learn more about their development and demise, the commonalities and dissonances between each branch.\n\nThis artifact is the most peculiar of all. You did well to bring it to me.", objectives = "Bring the Shimmering Timewarped Crystal to Kronnus in Warspear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55500] = { id = 55500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save A Friend", description = "In the cave ahead is where they are holding Mak. \n\nThey torture us. They break us. \n\nDon't let them take her, too.", completion = "We are deeply in your debt, land friend.", objectives = "Kill the Herald of the Queen to release Mak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55503] = { id = 55503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Direhorn and the Saurid", description = "<A gentle voice enters your mind.>\n\nI am pleased with your efforts. He will not soon forget the kindness you have shown him, and so he will not soon forget me.\n\nNow your journey will take you south. I can no longer sense one of my wayshrines. If you can determine what has happened to it and restore it, I would be grateful.", progress = "What did you learn?", completion = "<An amused voice enters your mind.>\n\nAh, the trickster Jani thought to amuse himself at my expense. I suppose that is the payment I have earned for stepping on his tail.\n\nThank you. This shrine will once again serve the Zandalari.", objectives = "Discover the fate of the central wayshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55504] = { id = 55504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayshrines of Zuldazar", description = "<A calm but thunderous voice enters your mind.>\n\nMy child grows under your care. I am pleased. Now, I would have your aid.\n\nThere was a time long ago when the roads of Zandalar were under my protection. Those who walked them gave praise, and in return I gave them my blessing. Fewer wander now.\n\nMy shrines remain, their purpose forgotten. You will help me to restore them.\n\nBegin in the north. See to the wayshrine there. If you find any lost travelers, see that they know my blessing through you.", progress = "Do you have de herbs?", completion = "Most of my goods have spoiled in de heat and rain, but take dis token of my appreciation.\n\nWe can finally go home.", objectives = "Restore the northern wayshrine and assist any travelers you come across.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55505] = { id = 55505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roo'li's Memory", description = "I was going to be a Dinomancer. Roo'li was going to grow with me as I learned.\n\n<Koo'li shakes her head.>\n\nDat future is gone now. Please, take him. Find a proper place to bury him.\n\nI... can't. De shame is too great.", progress = "<The great direhorn loa stares down at you.>\n\nWhat do you bring me, {name}?", completion = "<Torcali's voice rings in your mind.>\n\nHis time walking this world is done, but he will not be forgotten. He is returned to the soil, and with it his spirit lives on.", objectives = "Take Roo'li's remains to Torcali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55506] = { id = 55506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Road Ends", description = "<A warm voice enters your mind.>\n\nThere is one more wayshrine in this region that requires your attention.\n\nFollow this road until you near its end at the Port of Zandalar.\n\nIt is there, at the start and end of so many journeys, that one of my most trafficked shrines was established. Restore it and see that any weary travelers have my blessing.\n\nWe will speak again when you are finished.", progress = "Roo'li... Oh, Roo'li....", completion = "I should have protected him, but he stood his ground. Fierce little thing.\n\n<Koo'li pats Roo'li's head.>", objectives = "Restore the southern wayshrine and assist any travelers you come across.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55507] = { id = 55507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torcali's Blessing", description = "<Torcali's voice enters your mind.>\n\nYour actions speak to your intentions, {name}.\n\nI can see that my child will have the care she needs to grow strong, and grow she will. \n\nIn the coming days she will recover the strength that would have been hers, if nature had been allowed to take its course. Tend to her, earn her loyalty, and I will allow you to keep her at your side.\n\nThis is my gift to you.\n\nYou may go now. She will bring you to me when it is time.", completion = "<The Child of Torcali peers trustingly up at you.>", objectives = "Return the Child of Torcali to her nest in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55508] = { id = 55508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", completion = "Just what I wanted to hear!  A victory in Lake Wintergrasp - even a temporary one - is crucial to our overall strategy against the Horde.", objectives = "Win a Wintergrasp battleground match. You must have participated in the battle to be credited for the victory. Quest can only be auto completed while within the Battle for Wintergrasp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55509] = { id = 55509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", completion = "It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!", objectives = "Win a Wintergrasp battleground match. You must have participated in the battle to gain credit for the victory. Quest can only be auto completed while within the Battle for Wintergrasp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55510] = { id = 55510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", completion = "Glorious! Truly, you are among the champions of the Alliance.", objectives = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde. Quest can only be auto completed while within the Battle for Wintergrasp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55511] = { id = 55511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay them all!", description = "Welcome to the Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", completion = "Lok'tar! Victory for the Horde!", objectives = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance. Quest can only be auto completed while within the Battle for Wintergrasp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55516] = { id = 55516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spark of Genius", description = "{name}, I require your assistance.\n\nA recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras.\n\nInitial diagnostics suggest that these energies emanate from Hati, a legendary creature of lightning magic. This wolf was linked to the Titanstrike artifact, a weapon that proved instrumental in defeating the Legion!\n\nHati's spirit is still bound to Titanstrike's core, so I'll need your help. Meet me at my library in the Storm Peaks right away!", completion = "Our scientific team simply would not be complete without Bronzebeard here.\n\nLet's begin!", objectives = "Meet Mimiron at the Inventor's Library in the Storm Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55517] = { id = 55517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paint Vial: Big-ol Bronze", description = "<Marvelous Martini could make use of this item.>", completion = "One of my favorites!", objectives = "Deliver the item to Marvelous Martini.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55519] = { id = 55519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fresh Trauma", completion = "If we don't heal these wounds, the World Tree might not be standin' much longer.", objectives = "Meet Magni at Nordrassil in Mount Hyjal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55520] = { id = 55520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing Nordrassil", description = "Azerite elementals are runnin' wild, driven mad by Azeroth's pain. They're menacin' the spirits o' nature that protect the World Tree.\n\nThe roots o' Nordrassil run deep, nurtured by these sacred waters. For the sake o' Azeroth's world soul, the tree must be defended.\n\nQuiet the restless elementals and use yer Heart o' Azeroth tae mend the wounds ye find. We cannae let Hyjal become another gapin' scar like Silithus!", progress = "This just keeps gettin' worse. If too many wounds open up, we may not be able tae stop the cascade.", completion = "Ye did it, {name}! I can feel her pain diminishin'.\n\nAnd the Heart seems tae be even stronger now!", objectives = "Defeat Azerite elementals and seal Azeroth's injuries at Nordrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55521] = { id = 55521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do It the Azerite Way", description = "Incredible! Ye stopped the wound from spreadin' before it could get out o' control!\n\nNordrassil should be safe again, fer now. This is a good sign that we may just be able tae reverse all the damage done tae Azeroth.\n\nLet's get back tae the Chamber o' Heart, an' see if we can put any o' that azerite ye absorbed tae good use.", completion = "Additional azerite available for Heart of Azeroth. Activating now.", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55522] = { id = 55522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Heart", description = "Greetings, Champion of Azeroth.\n\nMOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger.\n\nAt least, we think she's pleased. It's difficult tae tell at times.\n\nRegardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", completion = "The Heart o' Azeroth feels stronger than ever. I wonder what amazing powers might be locked within!", objectives = "Return to the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55523] = { id = 55523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Locate murloc traders and obtain the items that Mrrl requires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55524] = { id = 55524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 5 Ghost Food, 5 Smelly Piles of Gloop, and 5 Sea Giant Foot Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55525] = { id = 55525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 4 Healthy Murloc Lunches, 3 Bags of Who-Knows-What, and 6 Sea Giant Foot Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55526] = { id = 55526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 15 Extra-Slimy Snails, 3 Smelly Piles of Gloop, and 5 Ghost Food.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55527] = { id = 55527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Him Some...", description = "<Mrrl points at your backpack then draws some pictures in the sand. He pulls out a pretty object from behind a rock then furiously points to himself then back at you then your bag.\n\nYou believe it might want to make a trade.>", objectives = "Bring Mrrl 3 Ghost Food, 3 Healthy Murloc Lunches, and 3 Sea Giant Foot Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55528] = { id = 55528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Playtime's Over", description = "The troggs have been raiding our supplies since we got here, but now that we got some fire power you're going to put a stop to that!\n\nLet's teach them troggs to stay away from our stuff!", progress = "Take out some troggs.", completion = "You earned your salary, {race}!", objectives = "Eliminate 12 Troggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55529] = { id = 55529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Backs", description = "<The murloc seems hungry. Next to it is a series of crude drawings which seems like a shopping list. Perhaps you can help the creature.>", progress = "Locate murloc traders and obtain the items that Mrrl requires.", completion = "<Mrrl eats the Slimy Naga Eyeball, squeezes the Flatulent Fish, rubs the Unidentified Mass on its feet, then throws the Sweet Sea Vegetable.\n\nIt looks satisfied.>", objectives = "Bring Mrrl a Sweet Sea Vegetable, an Unidentified Mass, a Flatulent Fish, and a Slimy Naga Eyeball.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55530] = { id = 55530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Safer Place", description = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Newhome.>", completion = "<Mrrl seems at home in his new spot and his family has also taken up refuge here. It is unlikely you will be able to remove this new murloc infestation.>", objectives = "Escort Mrrl back to Newhome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55531] = { id = 55531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Will It Mine?", description = "<Although worn from repeated use, the pickaxe still seems salvageable. Perhaps there's something nearby that can be mined?>", progress = "What have you brought me?", completion = "Ah, what do we have here? A rare find, indeed! \n\nBrinestone is quite volatile and should only be mined with special equipment. \n\nEven then, its collection frequently disturbs the elements, so mine with caution.", objectives = "Complete the Brinestone Cove event.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55533] = { id = 55533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "MOTHER Knows Best", description = "Now that this chamber's not fallin' tae pieces anymore, we can focus on makin' the Heart stronger!\n\nMOTHER says she's finished her fancy calculations. Have a word with her, champion. See if we can further empower the amazin' gift Azeroth gave ye.", progress = "Report: Ready for dissemination.\n\nChampion's response: Critical.", completion = "Analysis complete. In order to prevent planetary annihilation, Heart of Azeroth must be enhanced.\n\nObjective: Seek out compatible essences. Priority: Critical.", objectives = "Speak to MOTHER in the Chamber of Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55534] = { id = 55534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustbolt Gramophone", description = "<The large gramophone that you crafted is capable of blasting music across all of Rustbolt.\n\nNow, you just need to find a good place to install it.>", completion = "<This looks like a great place to install the gramophone.>", objectives = "Install the gramophone in the Rustbolt bar, The Tipsy Tinkerer.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55535] = { id = 55535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tipsy Tinkerer", description = "The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages.\n\nFind a spot to set it up in Rustbolt, and let the town know it's ready for use!", sourceObjective = "Install the Rustbolt Kegerator in Rustbolt's bar, The Tipsy Tinkerer.", completion = "This looks like a great place to install the kegerator.", sourceObjectiveStatus = "unverified-source-field" }
quests[55558] = { id = 55558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bolt Hole", description = "{name}, we must seek out a powerful weapon to combat the naga who guard the Tidal Conflux. I am certain such an object would be in the hands of one of Azshara's minions.\n\nThanks to our new allies, we've tracked down the location of one of her handmaidens within the ruins of Zin-Azshari. The journey will be quite dangerous. Thankfully our allies have a location nearby that we can use as a staging ground.\n\nI've marked the location on your map, meet with me there as soon as you can.", completion = "Yes. This place will do nicely. It is easily defended and has safe access to the ruins.", objectives = "Meet with Shandris Feathermoon at Utama's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55560] = { id = 55560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utama's Vengeance", description = "We Ankoan are a small tribe. There are not that many of us remaining.\n\nThis place was once overrun with makrura, before Utama. They tried to hide here, from the naga, but found the makrura. They fell, in battle, to the Kil'karrok.\n\nIf you wish to show your dedication to the Ankoan, become a force of vengeance in Utama's memory. Destroy the makrura.", progress = "We remember Utama. And honor their memory here.", completion = "You do Utama great honor by killing his foes.", objectives = "Kill 10 Makrura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55561] = { id = 55561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Remains of Zin-Azshari", description = "Zin-Azshari, once the capital of night elf civilization, was lost during the Sundering. Queen Azshara betrayed her people and allowed N'Zoth to corrupt them, turning them into naga.\n\nIt has now fallen into ruin and chaos.\n\nWe must see what it has become. Meet me by the statue of Azshara.", completion = "You must venture deeper into the city.", objectives = "Meet Shandris at the statue of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55565] = { id = 55565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoring Up Mana Reserves", description = "Holding back the tide walls is not an easy task, even using the Tidestone. The ebb and flow of the magical energies in the area are too inconsistent.\n\nWe need to shore up our magical reserves, which requires mana batteries, if you will. The befouled elementals along the canal here are created with exactly the elemental cores we need.\n\nThe goal is two fold. Clearing out the befouled elementals, before their corruption spreads, but also retrieving their cores, so we can keep the water at bay.", progress = "How goes your hunt?", completion = "We will get these back to Admiral Proudmoore.", objectives = "Collect 10 Elemental cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55569] = { id = 55569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of Pain", description = "These spirits... they are the Highborne. They were those Azshara held close. Azshara often played favorites, but these people... they were her favorites.\n\nI do not know why their spirits are here. We should investigate further. See if you can communicate with them and find out why their spirits cling to these ruins.\n\nHow could she abandon them?", completion = "I feel such sadness for these spirits. Eternally locked to this place, reliving the worst day of their lives.", objectives = "Speak with the spirits who wander around the Highborne Estates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55570] = { id = 55570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets in the Ruins", description = "This was once a place of great power. The highborne who lived here would host lavish parties, living in splendor.\n\nZin-Azshari was once on the shores of the Well of Eternity and drew powerful mages from all over the empire to study here. I suspect, despite the many years at the bottom of the sea, there are still treasures and powerful artifacts hidden away here.\n\nSpeak with the spirits that remain and see what you can find. There must be something to help us overcome the Guardian of the Tidestone.", progress = "What have you discovered, {name}?", completion = "The Javelins of Azshara? I've never heard of such an item. Unless they mean the Javelins of Suramar? That would be a wondrous find!", objectives = "Search for items of power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55571] = { id = 55571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Them See the Truth", description = "The information you have gleaned concerns me, {name}. These spirits cling to this place because they still, even now, believe in Azshara and her reign. She sold their lives to the void and they still believe in her.\n\nI know we have concerns that outweigh this, but I cannot leave them here like this.\n\nShow them. Confront them and tell them of Azshara's betrayal.", progress = "Have the spirits been put to rest?", completion = "Many of the spirits who haunt Zin-Azshari do not know they are dead. They will not admit it to themselves.\n\nWe might be able to help them. If you are willing to help me.", objectives = "Confront the spirits about Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55573] = { id = 55573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purging the Defilers", description = "Azshara always did need everything to be about her. Everything had to have her name on it. Everything was for her glory. She forgot our people's connection to Elune. Or perhaps she believed it did not matter?\n\nAzshara and her minions have too long defiled this place with their heresy.\n\nLet us show them Elune's vengeance.", completion = "Elune's vengeance is swift and fierce. Well done, {name}.", objectives = "Purge the naga from Elun'alor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55574] = { id = 55574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Javelins of Azshara", description = "These spirits keep speaking of the Javelins of Azshara. At first, I believed it to be referring to the handmaidens, who are currently holed up in Elun'alor.\n\nBut -- now I think they are referring to the Javelins of Suramar. They were powerful weapons -- long thought lost. Azshara does like to claim things as her own.\n\nWe need to defeat her handmaiden in Elun'alor regardless. Seizing the Javelins would be an amazing stroke of fortune.", progress = "Killing her handmaidens will drive the naga back and out of Zin-Azshari.", completion = "Killing a handmaiden alone would have been an amazing victory. Retrieving the Javelins of Suramar as well? Today is the turning point. Today, we have created the path to victory.", objectives = "Kill the Handmaiden of Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55575] = { id = 55575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Gnome's Trash", description = "The garbage in these trash heaps is full of rare metals: Dalaranium, Suramarite, even Gnomeisium! \n\nI've not seen this much easy gold to be had, since they left the vault door open in Boralus! You help me collect some of the metal, and my friend Gao will sell it on the black market.\n\nI've got a device that can tear the metal right out of the trash!", progress = "There's gold to be made!", completion = "This is going to sell quickly, here's your share of the profits to be!", objectives = "Collect 100 rare metals using the rare metal collector.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55578] = { id = 55578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: Jewel of the Tides", description = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it.\n\nSeamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point.\n\nA single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing.\n\nHowever, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", progress = "<Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", completion = "<As you affix the gem back into the center of the shrine, a strange pulse emanates from it.\n\nThe shrine, now whole again, begins to hum with energy.>", objectives = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55579] = { id = 55579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cracking the Surface", description = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist.\n\nAdditionally, the center jewel appears to have several cracks in it as well.\n\nChecking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest.\n\nPerhaps you can prospect the earth in that area to find more of those jewels.>", progress = "<The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", completion = "Using your tools, you carefully shape the jewels and affix them into the empty slots on the shrine.\n\nUsing the remainder, you are able to fill in the cracks of the center jewel, giving it a flush surface.\n\nAs you place the final jewel, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.", objectives = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55580] = { id = 55580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Prospects", description = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced.\n\nChecking your notes, you find that the earthen had extracted the gems from some earth elementals to the south.\n\nLooking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead.\n\nPerhaps investigating there will yield some clues as to where to find these jewels.>", progress = "<All of the cracked jewels will definitely need to be replaced.>", completion = "<You begin to remove all the cracked gems from the shrine and carefully start placing the new ones in.\n\nPlacing the final one, a pulse radiates from the shrine, as the light in the area seems to draw into it.\n\nThat strange, similar glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Investigate Gol Osigir for clues about the jewels that were used to construct the shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55581] = { id = 55581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sun-Speckled Dunes", description = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some.\n\nLooking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area.\n\nChecking your notes, it appears that these dunes were located south of your current location.>", progress = "<These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", completion = "<You carefully remove the old, weathered gems from the shrine and replace your polished gems in their place.\n\nAs you place the final gem, a similar pulse of energy radiates from the shrine as the light in the area seems to draw into it. A strange glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55582] = { id = 55582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atal'Dazar: Not All That Glitters...", description = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement.\n\nYou reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\".\n\nGiven your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", progress = "<When you're done replacing the central gem, you think you might still be able to sell the old one.>", completion = "<Returning to the shrine, you begin to pluck the old gem from its holding place. As you do, the gem cracks again and shatters in your hands.\n\nApparently these gems are much more fragile than you originally thought.\n\nVery carefully, you replace the gem you obtained into the slot.\n\nOnce affixed, a peaceful glow now emanating from the shrine leads you to believe it is once again active.>", objectives = "Travel to Atal'Dazar and find a replacement for the broken jewel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55583] = { id = 55583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out With the Old", description = "<Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites.\n\nIt's clear though that time has had its way with these gems, some eroded and chipped in places.\n\nRepairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", progress = "<Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", completion = "<Replacing each gem, they fit perfectly into the slots confirming your suspicions of their similarities.\n\nAs you place the final gem, the familiar pulse radiates once more from the shrine and the glow emanating from it confirms its restoration.>", objectives = "Cut 4 Natant Rubellites and replace the old ones with the new.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55585] = { id = 55585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Samuel has come across more locations.>", completion = "<You recount your findings of the Shrine of Storms to Samuel.>\n\nAnd you were able to repair the shrine? That's excellent news. Perhaps the next two will have a similar situation given their age and potential disuse.", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55586] = { id = 55586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polished Up", description = "<Samuel will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to him as soon as you're able.>", completion = "<You recount your findings about the shrine in Drustvar to Samuel.>\n\nHow fortunate for us that the inhabitants of that area used the same rocks to create their constructs from.\n\nI suppose luck is on our side in the quest for these shrines.", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55590] = { id = 55590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Things Right", description = "<Samuel will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through a prison.>", completion = "Oh, back already? That seemed quick. How'd it go?\n\n<You recount your finding of the shrine and the replacement of the gems.>\n\nThat does sound like quite the adventure! Excellent work, {name}.", objectives = "Return to Samuel D. Colton III in Boralus and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55591] = { id = 55591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Demolisher" }
quests[55592] = { id = 55592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Promising Beginning", description = "<The shrine now repaired, you find yourself eager to seek out the next shrine.\n\nPerhaps Seshuli has come across more locations.>", completion = "So de shrine used de same cut of gems we use? To think dat design has survived all dese years.\n\nYou know, dat may be de oldest recorded cut in history. Maybe even de first!\n\nBut it's good to hear you were able to repair de shrine. Maybe de other two will need to be fixed too, seeing as how dey are very old.", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55593] = { id = 55593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insight into Our Enemies", description = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. \n\nOur new allies have long been embattled with the naga. They would know best how to navigate these waters. \n\nSpeak with Blademaster Okani and see if they can provide some insight into how our enemies operate.", completion = "You wish to know more about the naga of Nazjatar? \n\nI am afraid these waters are as new to me as they are to you, but we may still be able to help each other.", objectives = "Speak to Blademaster Okani to learn more about the naga within Nazjatar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55594] = { id = 55594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Polished Up", description = "<Seshuli will surely want to hear about your progress on this shrine.\n\nYou feel as though you should report back to her as soon as you're able.>", completion = "<You recount your findings about the Vol'dun shrine to Seshuli>\n\nDat desert is a fools home if ya ask me. Good thing de shrine still stands dere and you were able to fix it.\n\nI'm still reading de journal trying to gather more information for you.", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55595] = { id = 55595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deteriorating Knowledge", description = "My clan came to Nazjatar, eager to destroy the naga queen. \n\nWe were not prepared for the darkness that she commands. \n\nOur scouts knew this land best, but their knowledge now deteriorates as their minds are controlled by Azshara's forces. \n\nFind and free our scouts, and you may still have a chance to access their knowledge.", completion = "Compelled to do the mindless bidding of our enemies is a fate worse than death. \n\nThere is no honor in that life.", objectives = "Rescue Imara, Adaru, and Umai from the clutches of mind-leeching Zoatroids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55596] = { id = 55596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Things Right", description = "<Seshuli will surely be interested to hear about your investigation into this shrine.\n\nMost assuredly the part where you had to fight your way through Atal'Dazar.>", completion = "<You recount your experience at the shrine with Seshuli.>\n\nTraveled ta Atal'Dazar, eh? Dat place is quite amazing from what I remember.\n\nStill though, great job on repairing de shrine.", objectives = "Return to Seshuli in Dazar'alor and report on your discovery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55597] = { id = 55597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound by Honor", description = "It is true that my clan has been battling the naga for generations, but it was only in recent times that we took the fight to Nazjatar. \n\nOur leader was slain by the vile queen, and now honor binds my clan to this deep ocean. \n\nWe will avenge their death or die here trying. It is our way. \n\nYour mission aligns with our duty, so we will fight the naga together. \n\nSlay their forces and bring us one step closer to honoring our promise.", completion = "You fight like an Ankoan. You bring my clan honor with your actions today.", objectives = "Kill 10 naga within Zanj'ir Wash and the Deepsea Slave Pens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55598] = { id = 55598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What We Know of the Naga", description = "I owe you a debt. That much is clear. \n\nMy mind still reels from the zoatroid's influence, but I fear the others suffer more visible wounds. \n\nApply this salve to their wounds, and I will do my best to share what I know of the naga.", progress = "I will tell you what I know of the naga.", completion = "Whatever is hidden within the stronghold needs to be destroyed.", objectives = "Tend to the Ankoan's wounds and hear what Adaru has to say about the naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55599] = { id = 55599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Undercover", description = "Entering the stronghold alone would be a death wish. \n\nThe Zanj'ir slaughter outsiders on sight. \n\nThe only way to get in without being killed is to appear to be under the effects of a zoatroid. \n\nEven then, the mind-shackled are put to work. \n\nYou must obey all commands, or they will know your mind is still your own. \n\nOnce the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", completion = "What use are you if you're not working?", objectives = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55600] = { id = 55600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sating Snapdragons", description = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. \n\nThe beasts will eat anything, including your arm if you don't move it away quickly enough. \n\nLuckily for you, they've developed a taste for Chitterspine Roe.", completion = "I'm surprised they didn't make a meal out of you.", objectives = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55601] = { id = 55601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coveted Crystals", description = "Locating the weapons cache should not be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all that is needed.\n\nIt all seems rather simple, does it not? But the key is in the Deepsea Crystal used to refract the light. \n\nThe Bloodfin tribe covets these crystals, so you should have no trouble obtaining one.", progress = "Have you found the crystal?", completion = "I can see why the Bloodfin covet these crystals. The gem is unlike any I've seen before.", objectives = "Collect a Deepsea Crystal from Hoarder Moarrgl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55602] = { id = 55602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Will It Lure?", description = "<Putrid and pungent, this lump of bait is the preferred food of skittering eels. Perhaps you can find infested waters nearby?>", progress = "What have you brought me?", completion = "Ah, what do we have here? A rare find, indeed! \n\nYou've been chumming the waters I see! \n\nJust be careful. \n\nEels aren't the only creatures that you'll attract with that bait.", objectives = "Chum the Eel Infested Waters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55608] = { id = 55608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shop Project", description = "As a reward for all your help here, I was planning to fix this old mechaspider mount to give to you.\n\nI could use some more of your help though to get this project started!\n\nI'll need parts off a few of the bots nearby, and maybe you could talk to Cork Stuttgard at Bondo's Yard and see if you can get a Mechanobot Ignition system.", progress = "Did you find those parts yet?", completion = "These parts will get us started, but there's a lot of work to do still.", objectives = "Acquire Shellsteel Plating, Multi-Leg Chaindrive, and a Mechanobot Ignition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55609] = { id = 55609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Mechagon - The Mechoriginator", description = "My father's madness won't be contained to this island.\n\nKing Mechagon is creating a massive device capable of reversing the Curse of Flesh across the entirety of Azeroth!\n\nAny races forged by the Titans will return to their original state. For us gnomes, that means fully mechanical. For dwarves and troggs, stone. Vrykul, iron.\n\nThe list goes on, but most races aren't even ON the list. Anything not forged by the titans will be completely obliterated.\n\nWe must stop King Mechagon before it's too late!", progress = "King Mechagon's madness threatens all of us. We must stop my father!", completion = "That robot... that AI... was not my father.\n\nMy father died the day he abandoned his body and soul for full mechanization. The day he betrayed our people.\n\nThe burden of leadership has rested on my shoulders for some time... Only now, do I feel I can embrace it.\n\nI will lead my people with wisdom, ingenuity, and humility. Thank you, {name}.", objectives = "Enter Mechagon and defeat King Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55613] = { id = 55613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55614] = { id = 55614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55617] = { id = 55617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expedition Siege Engine" }
quests[55618] = { id = 55618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart Forge", description = "Rise in Heart Forge energy levels indicates presence of black dragon essence.\n\nRecommendation: Initiate Heart Forge activation sequence.", progress = "Data calculations complete. Awaiting initiation of forge activation sequence.", completion = "Power source accepted. Forge activation complete.", objectives = "Speak with MOTHER to activate the Heart Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55619] = { id = 55619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrade Your Vehicle (Optional)" }
quests[55622] = { id = 55622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive It Away Today", description = "The mount's all polished up and looking great. We are almost done!\n\nI gave the Powercore Schematics to PASCAL-K1N6. He's ready to build us a new 500S-Cybergenic Powercore, once you get him the parts.\n\nWe install that powercore and you can drive this bot away today!", progress = "Did you get the core?", completion = "They won't be stealing from us anymore!", objectives = "500S-Cybergenic Powercore obtained.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55625] = { id = 55625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearls of Unimaginable Power", description = "Thousands of years ago, when the Well of Eternity was destroyed and this land plummeted to the depths of the ocean, a great storm of magical energy was unleashed.\n\nRemnants of this magical energy still exist today.\n\nGather the pearls from the ancient mana-infused clams. These enchanted pearls may be powerful weapons in our fight against the naga!", progress = "We must make use of every advantage in our fight against the naga.", completion = "You have done well. I can sense a powerful energy from emanating from within these pearls.", objectives = "Collect 8 Enchanted Pearls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55627] = { id = 55627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55628] = { id = 55628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[55630] = { id = 55630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Get It Started", description = "Those gnomes think busting up machinery is gonna stop a goblin like me from figuring out what all the tech in this place does?\n\nI ain't never seen a hunk of junk so busted up that ol' Skaggit and I can't get running smoother than the day it was made.\n\nTell ya what. You head around with Skaggit and see what you can piece back together.\n\nMeanwhile, I'll have a chat with our gnome friend here and see what she knows about all this tech.", progress = "We'll have this place up and running in no time.", completion = "<Gazlowe's ears perk up and he listens intently for a few moments.>\n\nMachine sounds good. Few loose bolts and missing wires, but nothin' we'd really miss.\n\nNice work.", objectives = "Repair the vault's machinery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55632] = { id = 55632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Must be This Height", description = "You and the Greasemonkeys got this machine up and running even faster than I expected.\n\nThe gnome we captured is keeping her mouth shut, but that shouldn't be a problem. I can take it from here.\n\nLet me know when you're ready. I'll crank up this machine to max and we'll finally see what it can do.\n\nI hope it prints gold coins...", progress = "That's the best use of a gnome I've ever seen!", completion = "Phew. Close call there, but the risk is gonna pay out big.\n\nDid you see the sweet tech King Mechagon was wearing? We gotta get our hands on that!", objectives = "Tell Gazlowe to activate the device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55633] = { id = 55633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sunken Chest", description = "<This waterlogged chest appears to be in salvageable condition, but it is too heavy to move due to the contents within.\n\nThe lock on the device appears to be operational.\n\nPerhaps there is a key nearby...>", progress = "<The chest is locked and requires a key.>", completion = "<It takes some effort, but the lock eventually opens...>", objectives = "Locate the Brass Key at the bottom of the lagoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55635] = { id = 55635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice on the Wind", description = "<A distant, mysterious voice fills your mind.>\n\nMy enchantments are not lost...\n\nFind me...\n\nDrustvar...\n\nFallhaven...", completion = "Be at ease, friend. I don't want to hurt you. Instead, I have a proposition for you.\n\nYou see, I was a druid once and the only thing I loved more than tending to the forests and creatures within them was enchanting. \n\nThen I was murdered and cursed to wander this peninsula, unable to cross river nor mountain so long as my body still exists. \n\nIf you destroy my old body and help me make a new one, I will teach you how I made the rod you disenchanted.", objectives = "Seek out the source of the mysterious voice in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55636] = { id = 55636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Life's Work", description = "<A voice whispers to you from beyond the veil of death.>\n\nI spent more than one-thousand years researching the mysteries of the arcane before the Great Sundering tore our world apart.\n\nI perished amidst the destruction and my work was lost.\n\nSearch the area for my ancient writings and put my spirit to rest...", progress = "The bookcase appears empty...", completion = "With the arcane tomes and ancient scrolls restored to the bookcase, it feels as though a long held weight has been lifted from your shoulders.", objectives = "Collect 6 Ancient Scrolls and 6 Arcane Tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55637] = { id = 55637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poor, Unfortunate Souls", description = "Countless lives were lost in the Great Sundering when this great city was plunged into the depths of the abyss.\n\nThe fortunate among us died quickly in the explosion, but some survived only to cling onto dear life as the cold, unforgiving ocean waves crashed down upon them.\n\nThose poor, unfortunate souls suffer a fate worse than death to this day. They drown endlessly, forced to relive the torture of their death.\n\nPut them to rest so that they may have peace at last.", progress = "I hear them as we speak... crying out for help. Yet, I am powerless to save them...", completion = "They will never gain back the lives they lost that day so long ago, but at least they will suffer no longer.", objectives = "Put 8 Tortured Souls to rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55638] = { id = 55638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Kelpberry Wine", description = "<This is an empty kelpberry juice cask.\n\nThere is someone nearby that may appreciate a refill.>", progress = "Did you bring me something?", completion = "Oh, you know exactly what this ol' girl likes!", objectives = "Deliver Kelpberry Wine to Maedin in Maedin's Challenge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55639] = { id = 55639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Lurks in the Pit", description = "The winds whisper of people being trapped in the pit. It seems there may be more members of the expedition within.\n\nI fear it will be up to you to make the descent and save the survivors.\n\nThere should be six in total...  though the winds say that one is farther away from the others...\n\nWith our luck, the last survivor is at the bottom of the pit.\n\nGood luck, {name}. And... make sure no spiders follow you back out.", completion = "Ralia Dreamchaser is a druid of the Cenarion Circle, an order dedicated to protecting the wilds of Azeroth.\n\nThank you for rescuing her. Her aid is sure to be of use against the ogres.", objectives = "Rescue 5 Trapped Expedition Members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55640] = { id = 55640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision of Stormwind", description = "Weaken N'Zoth by delving into his mind.", objectives = "Complete the Vision of Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55645] = { id = 55645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Princely Visit", description = "This is it! The fabled Mechagon!\n\nThe greatest discovery of our age, and you're here to witness me accomplish it!\n\n<Tinkmaster Overspark puffs out his chest, brushes off his robes, and smiles confidently.>\n\nI am ready to address the Mechagon people. You may accompany me.", progress = "Mechagon is not like the legends you were told.", completion = "Welcome to the Rustbolt Resistance.", objectives = "Explore the nearby town with Tinkmaster Overspark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55646] = { id = 55646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Mechagon", completion = "Keep your head down! The Alliance beat us here!", objectives = "Meet Gazlowe at the Abandoned Junkheap in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55647] = { id = 55647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Quick Ear Hustle", description = "Bad news. We're late.\n\nThe Alliance was already crawling all over the vault when we got here.\n\nLucky for us, some big commotion inside sent some of 'em running for the hills.\n\nMost of 'em are still down in that vault, though, including that crazy braggart Tinkmaster Overspark.\n\nLet's give 'em a few more minutes to clear out, so we don't have to go in guns blazing.", progress = "What'd they find down there?", completion = "Told you that Overspark was a chump.\n\nA boss has gotta respect his crew, or they won't respect him.", objectives = "Wait for the Alliance to leave the vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55648] = { id = 55648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This is Our Vault Now", description = "Looks like the coast is clear with Overspark gone. Let's get inside that vault and see what's really going on here.\n\nMechagon or not, there'd better be some quality hardware in there to make this trip worth our time.", completion = "Easy peasy. Now we just gotta get all this fancy gnomish machinery workin' again!", objectives = "Lead Gazlowe's crew into the vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55649] = { id = 55649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machinations for Mechagon", description = "So Mechagon ain't just a fairy tale? Gotta admit I'm surprised.\n\nBut, if the tech on that king is any indication of what they've got out there for us to swipe, I am very, very happy to be wrong!\n\nWe can't rush into this. A good crew died today. That ain't happening again on my watch.\n\nMeet me and Skaggit back in Zuldazar Harbor, and we'll build this expedition up right.", completion = "Feels good to be back on Horde turf.", objectives = "Ride the Greasemonkey Skysneaker to Zuldazar Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[55650] = { id = 55650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Only the Best Will Do", description = "You heard Gazlowe. The boss wants this expedition to go smoothly. No cutting corners, no slush.\n\nI know you've worked with Gallywix in the past. We don't run our operations like that.\n\nWe expect the best from our crews, so we pay 'em what they're worth and treat 'em well. In return, we got the best goblin crews on the planet, and they ain't goin' over to any competition.\n\nHere's a list of who and what we're gonna need to pull this off. Don't worry, Gazlowe'll cover all the costs.", progress = "Look, {name}, I ain't got time to hold your hand through all this. Figure it out or I'll find someone else who will.", completion = "This might be the best crew Gazlowe and I have ever assembled!", objectives = "Get everything needed to launch the expedition for Mechagon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
